      ovPause: 'ov-pause', pauseMenu: 'pause-menu', pauseHelp: 'pause-help', pauseSub: 'pause-sub',
      resumeBtn: 'btn-resume', restartBtn: 'btn-restart', helpBtn: 'btn-help', helpBack: 'btn-help-back',
