/* UI test harness — loaded by game/index.html ONLY with ?stubs=1 (never packaged for Android).

   Minimal fake WW.sim.createRace and WW.render.createRenderer implementing the docs/ARCHITECTURE.md §7/§8 contract
   surface the UI uses, so HUD, overlays, input and the loop can be exercised before the real modules exist.

   Fake race: walks WW.LEVEL.route at 5 m/s; halts at each plate's `stop` until the stitch is tapped (stitch becomes
   'ready', a tap animates it open); collects purl.* at the plate pickup fractions; on the landing Snagling hops at the
   reveal f — a jump (swipe up) dodges, otherwise a hit drops the newest thread one lane right (swipe right + run over
   it = THREAD RECOVERED; missing it runs a recovery loop); a hit at 0 threads fails. Loop runs his own lengths with
   short task pauses and picks up his IDs. Finish requires 3/3; results keep loopStillRacing until Loop arrives.
   ?scenario=win (default) | lose (fast Loop) | fail (no pickups, so the landing hit at 0 fails)
   race.debug: teleport(who, segId, f), setHeld(who, n), forceFail(), forceFinish(loopFirst), message(text, kind). */
(function (WW) {
  'use strict';

  const params = new URLSearchParams(location.search);
  const SCENARIO = params.get('scenario') || 'win';
  const T = WW.TUNING || {};
  const COLORS = ['coral', 'teal', 'gold'];

  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }

  function plateEvents(plates, plateId, who) {
    const p = plates && plates[plateId];
    return (p && p[who] && p[who].events) || [];
  }

  function createRace(opts) {
    const level = opts.level || WW.LEVEL;
    const plates = opts.plates || WW.PLATES || {};
    const seed = opts.seed >>> 0;
    const rng = WW.rng ? WW.rng(seed) : { range: function (a, b) { return (a + b) / 2; } };
    const route = level.route, loopRoute = level.loopRoute || level.route;
    const loopSpeed = (SCENARIO === 'lose' ? 5.9 : 5.0) * rng.range(0.96, 1.04);

    /* per-segment authored fractions (with fallbacks when plate data is incomplete) */
    const segInfo = route.map(function (seg) {
      const info = { stop: null, pickup: null, reveal: null, finish: null };
      if (seg.kind !== 'plate') return info;
      plateEvents(plates, seg.plate, 'purl').forEach(function (e) {
        if (e.type === 'stop') info.stop = { stitch: e.stitch, f: Math.max(0.04, e.f + 0.04), readyF: e.readyF || 0 };
        if (e.type === 'pickup') info.pickup = { item: 'purl.' + e.item, f: e.f };
        if (e.type === 'reveal') info.reveal = e.f;
        if (e.type === 'finish') info.finish = e.f;
      });
      if (seg.id === 'landing' && info.reveal == null) info.reveal = 0.25;
      if (seg.id === 'finish' && info.finish == null) info.finish = 0.6;
      return info;
    });
    const loopInfo = loopRoute.map(function (seg) {
      const info = { task: null, pickup: null, finish: null };
      if (seg.kind !== 'plate') return info;
      plateEvents(plates, seg.plate, 'loop').forEach(function (e) {
        if (e.type === 'pickup') info.pickup = { item: 'loop.' + e.item, f: e.f };
        if (e.type === 'finish') info.finish = e.f;
      });
      if (['ribbon', 'shortcut', 'tassels', 'tapestry'].indexOf(seg.id) >= 0) info.task = { f: 0.15, dur: 1.6 };
      if (seg.id === 'finish' && info.finish == null) info.finish = 0.5;
      return info;
    });

    const items = {};
    ['purl', 'loop'].forEach(function (owner) {
      COLORS.forEach(function (c) {
        const id = owner + '.' + c;
        const segs = owner === 'purl' ? segInfo : loopInfo;
        let seg = 0, f = 0.5;
        segs.forEach(function (s, i) { if (s.pickup && s.pickup.item === id) { seg = i; f = s.pickup.f; } });
        items[id] = { id: id, owner: owner, color: c, status: 'uncollected', available: c !== 'gold',
          seg: route[seg].id, f: f, lane: 0, heldSeq: 0, dropTime: null };
      });
    });
    if (SCENARIO === 'fail') COLORS.forEach(function (c) { items['purl.' + c].available = false; });

    const state = {
      mode: 'intro', paused: false, pauseReason: null, time: 0, countdown: T.countdown || 3, seed: seed,
      purl: { seg: 0, segId: route[0].id, f: 0, lane: 0, laneX: 0, jumpT: 0, jumpH: 0, speed: 0, action: 'idle',
        airborne: false, immuneUntil: 0, tangledUntil: 0, distance: 0, finishTime: null, rank: null },
      loop: { seg: 0, segId: loopRoute[0].id, f: 0, laneX: 0.6, jumpH: 0, speed: 0, action: 'idle', task: null,
        distance: 0, finishTime: null, rank: null },
      items: items,
      held: { purl: 0, loop: 0 },
      stitches: {
        ribbon: { state: 'idle', t: 0, tappedAt: null }, shortcut: { state: 'idle', t: 0, tappedAt: null },
        tassels: { state: 'idle', t: 0, tappedAt: null, lifts: [0, 0, 0] },
        butterfly: { state: 'idle', t: 0, tappedAt: null, phase: 'dormant' }
      },
      loopTasks: {},
      snagling: { state: 'concealed', t: 0, targetLane: 0, contactF: null, result: null, pass: 0, armed: true, contactConsumed: false },
      gate: { state: 'closed', t: 0 },
      objective: route[0].objective, phase: route[0].phase,
      message: null, hint: null, transition: null, result: null,
      stats: { hits: 0, dodges: 0, recoveries: 0, taps: 0 }
    };
    let seq = 0, holdSeq = 0, loopTaskLeft = 0, loopTaskDone = {};
    let finishWait = 0, failAt = null, jumpBuffer = 0;

    function seg() { return route[state.purl.seg]; }
    function info() { return segInfo[state.purl.seg]; }
    function say(text, kind, dur) { state.message = { text: text, kind: kind || 'info', until: state.time + (dur || 1.6) }; }
    function recount() {
      let p = 0, l = 0;
      Object.keys(items).forEach(function (k) { if (items[k].status === 'held') { if (items[k].owner === 'purl') p++; else l++; } });
      state.held.purl = p; state.held.loop = l;
    }
    function objectiveFor() {
      const s = seg(), inf = info();
      if (!s.objective) return state.objective;
      if (s.id === 'landing') {
        const dropped = Object.keys(items).some(function (k) { return items[k].owner === 'purl' && items[k].status === 'dropped'; });
        return dropped && s.objectiveDrop ? s.objectiveDrop : s.objective;
      }
      const st = inf.stop && state.stitches[inf.stop.stitch];
      if (st && st.state === 'open') {
        const pk = inf.pickup && items[inf.pickup.item];
        if (pk && pk.status === 'held') return s.objectiveDone || s.objectiveOpen || s.objective;
        return s.objectiveOpen || s.objective;
      }
      return s.objective;
    }

    function enterSeg(i, ev) {
      state.purl.seg = i; state.purl.segId = route[i].id; state.purl.f = 0;
      const s = route[i];
      if (s.kind === 'plate') { state.phase = s.phase || state.phase; }
      state.transition = s.kind === 'connector' ? { kind: 'connector', from: s.from, to: s.to, style: s.style, t: 0 } : null;
      if (s.id === 'landing') { state.snagling.state = 'concealed'; state.snagling.armed = true; state.snagling.pass++; state.snagling.contactConsumed = false; state.snagling.result = null; }
      ev.push({ type: 'segment', who: 'purl', segId: s.id });
    }

    function stepPurl(dt, ev) {
      const p = state.purl, s = seg(), inf = info();
      // jumping
      if (p.jumpT > 0) {
        p.jumpT = Math.max(0, p.jumpT - dt / (T.jumpTime || 0.68));
        p.jumpH = Math.sin(Math.PI * (1 - p.jumpT));
        if (p.jumpT === 0) { p.jumpH = 0; if (jumpBuffer > 0) { jumpBuffer = 0; p.jumpT = 1; ev.push({ type: 'jump', who: 'purl' }); } }
      }
      jumpBuffer = Math.max(0, jumpBuffer - dt);
      p.airborne = p.jumpH > (T.jumpAirborneAbove || 0.3);
      p.laneX += clamp(p.lane - p.laneX, -dt / (T.laneChangeTime || 0.22), dt / (T.laneChangeTime || 0.22));

      let speed = 5;
      if (state.time < p.tangledUntil) { speed = 0; p.action = 'tangled'; }
      else p.action = s.kind === 'connector' ? 'transition' : 'run';

      let limit = 1;
      if (inf.stop) {
        const st = state.stitches[inf.stop.stitch];
        if (st.state === 'idle' && p.f >= inf.stop.readyF) { st.state = 'ready'; }
        if (st.state !== 'open') limit = inf.stop.f;
        if (st.state === 'ready' && p.f >= inf.stop.f - 1e-6) {
          state.hint = { text: 'Tap the glowing stitch', until: state.time + 0.5 };
        }
      }
      const df = speed * dt / s.length;
      p.f = Math.min(limit, p.f + df);
      if (p.f >= limit - 1e-6 && limit < 1) { p.action = 'wait'; p.speed = 0; } else { p.speed = speed; p.distance += speed * dt; }
      if (state.transition) state.transition.t = p.f;

      // pickups / recovery
      Object.keys(items).forEach(function (k) {
        const it = items[k];
        if (it.owner !== 'purl' || it.seg !== s.id || !it.available || it.status === 'held') return;
        if (Math.abs(p.f - it.f) > (T.pickupRadiusF || 0.035)) return;
        if (it.status === 'dropped' && Math.abs(p.laneX - it.lane) >= (T.dropPickupLane || 0.6)) return;
        const wasDropped = it.status === 'dropped';
        it.status = 'held'; it.heldSeq = ++holdSeq; recount();
        if (wasDropped) { state.stats.recoveries++; say('THREAD RECOVERED', 'recover', 1.8); ev.push({ type: 'recover', item: k }); }
        else ev.push({ type: 'pickup', item: k });
      });

      // Snagling on the landing
      if (s.id === 'landing') stepSnag(dt, ev);

      // finish
      if (s.id === 'finish' && p.f >= inf.finish && p.finishTime == null) {
        if (state.held.purl >= 3) {
          p.finishTime = state.time; p.rank = state.loop.finishTime != null ? 2 : 1; p.action = 'finished';
          state.mode = 'finished'; state.gate.state = 'opening';
          state.objective = s.objectiveDone || 'LEVEL 1 COMPLETE';
          ev.push({ type: 'gate-open' }, { type: 'finish', who: 'purl', time: p.finishTime });
          updateResult();
          return;
        }
        say('A THREAD IS MISSING', 'info', 2.2);
        ev.push({ type: 'gate-blocked' });
        const li = route.findIndex(function (r) { return r.id === 'landing'; });
        enterSeg(li, ev); p.f = 0.05;
        state.transition = { kind: 'return', from: 'finish', to: 'landing', t: 0 };
        return;
      }
      if (p.f >= 1) {
        // recovery loop if a thread is still on the landing
        if (s.id === 'landing' && Object.keys(items).some(function (k) { return items[k].owner === 'purl' && items[k].status === 'dropped'; })) {
          enterSeg(state.purl.seg, ev); p.f = 0.08;
          state.transition = { kind: 'loop', from: 'landing', to: 'landing', t: 0 };
          return;
        }
        if (state.purl.seg < route.length - 1) enterSeg(state.purl.seg + 1, ev);
      }
      if (state.transition && state.transition.kind !== 'connector') {
        state.transition.t += dt / 1.2;
        if (state.transition.t >= 1) state.transition = null;
      }
    }

    function stepSnag(dt, ev) {
      const sn = state.snagling, p = state.purl, inf = info();
      sn.t += dt;
      if (sn.state === 'concealed' && sn.armed && p.f >= inf.reveal) {
        sn.state = 'hop'; sn.t = 0; sn.targetLane = p.lane; sn.armed = false; sn.contactConsumed = false;
        ev.push({ type: 'reveal' });
      } else if (sn.state === 'hop' && sn.t >= (T.snagRevealToContact || 0.55) && !sn.contactConsumed) {
        sn.contactConsumed = true;
        const contact = Math.abs(p.laneX - sn.targetLane) < 0.55 && p.jumpH < (T.jumpAirborneAbove || 0.3);
        if (!contact) { sn.result = 'dodge'; sn.state = 'retreat'; sn.t = 0; state.stats.dodges++; ev.push({ type: 'dodge' }); return; }
        if (state.time < p.immuneUntil) { sn.result = 'immune'; ev.push({ type: 'immune-ignored' }); sn.state = 'retreat'; sn.t = 0; return; }
        sn.result = 'hit'; state.stats.hits++; ev.push({ type: 'hit' });
        const held = Object.keys(items).filter(function (k) { return items[k].owner === 'purl' && items[k].status === 'held'; });
        if (!held.length) { failAt = state.time + (T.failDelay || 1.2); p.tangledUntil = failAt + 5; sn.state = 'tangle'; sn.t = 0; return; }
        held.sort(function (a, b) { return items[b].heldSeq - items[a].heldSeq; });
        const it = items[held[0]];
        it.status = 'dropped'; it.seg = 'landing'; it.f = Math.min(0.85, p.f + (T.dropAheadF || 0.1)); it.lane = p.lane === 1 ? 0 : 1; it.dropTime = state.time;
        recount();
        say('SNAGGED!', 'hit', 1.6);
        p.tangledUntil = state.time + (T.snagTangle || 0.5); p.immuneUntil = state.time + (T.hitImmunity || 1.6);
        sn.state = 'tangle'; sn.t = 0;
        ev.push({ type: 'drop', item: it.id, f: it.f, lane: it.lane });
      } else if (sn.state === 'tangle' && sn.t > (T.snagTangle || 0.5)) { sn.state = 'retreat'; sn.t = 0; }
      else if (sn.state === 'retreat' && sn.t > (T.snagRetreat || 1.4)) { sn.state = 'done'; }
    }

    function stepLoop(dt, ev) {
      const l = state.loop;
      if (l.finishTime != null) return;
      const s = loopRoute[l.seg], inf = loopInfo[l.seg];
      if (loopTaskLeft > 0) {
        loopTaskLeft -= dt; l.action = 'task'; l.speed = 0;
        if (loopTaskLeft <= 0) { l.task = null; }
        return;
      }
      if (inf.task && !loopTaskDone[s.id] && l.f >= inf.task.f) {
        loopTaskDone[s.id] = true; loopTaskLeft = inf.task.dur; l.task = { kind: 'stitch', until: state.time + inf.task.dur };
        ev.push({ type: 'loop-task', kind: 'stitch' });
        return;
      }
      l.action = s.kind === 'connector' ? 'transition' : 'run'; l.speed = loopSpeed;
      l.f += loopSpeed * dt / s.length; l.distance += loopSpeed * dt;
      if (inf.pickup) {
        const it = items[inf.pickup.item];
        if (it.status === 'uncollected' && l.f >= inf.pickup.f) {
          it.available = true; it.status = 'held'; it.heldSeq = ++holdSeq; recount();
          ev.push({ type: 'pickup', item: it.id });
        }
      }
      if (s.id === 'finish' && l.f >= inf.finish && state.held.loop >= 3) {
        l.finishTime = state.time; l.rank = state.purl.finishTime != null ? 2 : 1; l.action = 'finished';
        ev.push({ type: 'finish', who: 'loop', time: l.finishTime });
        updateResult();
        return;
      }
      if (l.f >= 1 && l.seg < loopRoute.length - 1) { l.seg++; l.segId = loopRoute[l.seg].id; l.f = 0; ev.push({ type: 'segment', who: 'loop', segId: l.segId }); }
      l.f = Math.min(l.f, 1);
    }

    function updateResult() {
      const p = state.purl, l = state.loop;
      if (p.finishTime == null) return;
      state.result = {
        purlTime: p.finishTime, loopTime: l.finishTime, purlRank: p.rank, loopRank: l.rank,
        winner: p.rank === 1 ? 'purl' : 'loop', loopStillRacing: l.finishTime == null && finishWait < (T.finishWaitForLoop || 25)
      };
    }

    function stepStitches(dt, ev) {
      Object.keys(state.stitches).forEach(function (id) {
        const st = state.stitches[id];
        if (st.state !== 'animating') return;
        const dur = id === 'ribbon' ? (T.ribbonUnfurl || 1.3) : id === 'shortcut' ? (T.shortcutUnroll || 1.5)
          : id === 'tassels' ? 1.05 : 2.85;
        st.t = Math.min(1, st.t + dt / dur);
        if (id === 'tassels') st.lifts = [0, 1, 2].map(function (i) { return clamp((st.t * 1.05 - i * 0.28) / 0.45, 0, 1); });
        if (id === 'butterfly') st.phase = st.t < 0.25 ? 'emerge' : st.t < 0.85 ? 'fly' : 'place';
        if (st.t >= 1) {
          st.state = 'open';
          if (id === 'butterfly') { st.phase = 'done'; if (SCENARIO !== 'fail') items['purl.gold'].available = true; }
          ev.push({ type: 'stitch-open', id: id });
        }
      });
    }

    function step(dt) {
      const ev = [];
      if (state.paused || state.mode === 'intro' || state.mode === 'failed') return ev;
      if (state.mode === 'countdown') {
        state.countdown -= dt;
        if (state.countdown <= 0) { state.countdown = 0; state.mode = 'running'; state.time = 0; ev.push({ type: 'go' }); }
        return ev;
      }
      state.time += dt;
      if (state.mode === 'running') {
        stepStitches(dt, ev);
        stepPurl(dt, ev);
        if (failAt != null && state.time >= failAt) { state.mode = 'failed'; state.purl.action = 'failed'; ev.push({ type: 'fail' }); }
      } else if (state.mode === 'finished') {
        finishWait += dt;
        state.gate.t = Math.min(1, state.gate.t + dt / 1.2);
        if (state.gate.t >= 1) state.gate.state = 'open';
      }
      stepLoop(dt, ev);
      if (state.mode === 'finished') updateResult();
      if (state.mode === 'running') state.objective = objectiveFor();
      if (state.message && state.time > state.message.until) state.message = null;
      if (state.hint && state.time > state.hint.until) state.hint = null;
      return ev;
    }

    function input(cmd) {
      const ev = [];
      if (!cmd || state.paused || state.mode !== 'running') return ev;
      const p = state.purl;
      if (cmd.type === 'tap') {
        state.stats.taps++;
        const st = state.stitches[cmd.target];
        if (st && st.state === 'ready') { st.state = 'animating'; st.t = 0; st.tappedAt = state.time; state.hint = null; ev.push({ type: 'stitch-tap', id: cmd.target }); }
      } else if (cmd.type === 'swipe') {
        if (cmd.dir === 'up') {
          if (p.jumpT > 0) { if (p.jumpT < 0.25) jumpBuffer = T.inputBufferTime || 0.15; }
          else { p.jumpT = 1; ev.push({ type: 'jump', who: 'purl' }); }
        } else if (cmd.dir === 'left' || cmd.dir === 'right') {
          if (seg().id === 'landing') {
            const nl = clamp(p.lane + (cmd.dir === 'left' ? -1 : 1), -1, 1);
            if (nl !== p.lane) { p.lane = nl; ev.push({ type: 'lane', who: 'purl', lane: nl }); }
          }
        }
      }
      return ev;
    }

    return {
      state: state,
      step: step,
      input: input,
      start: function () { if (state.mode === 'intro') { state.mode = 'countdown'; state.countdown = T.countdown || 3; } return []; },
      pause: function (reason) { state.paused = true; state.pauseReason = reason || 'user'; return []; },
      resume: function () { state.paused = false; state.pauseReason = null; return []; },
      debug: {
        teleport: function (who, segId, f) {
          const r = who === 'loop' ? loopRoute : route;
          const i = r.findIndex(function (s) { return s.id === segId; });
          if (i < 0) return;
          if (who === 'loop') { state.loop.seg = i; state.loop.segId = segId; state.loop.f = f || 0; }
          else { enterSeg(i, []); state.purl.f = f || 0; state.phase = route[i].phase || state.phase; state.objective = objectiveFor(); }
        },
        setHeld: function (who, n) {
          COLORS.forEach(function (c, i) {
            const it = items[who + '.' + c];
            it.status = i < n ? 'held' : 'uncollected'; it.available = true; it.heldSeq = i < n ? ++holdSeq : 0;
          });
          recount();
        },
        openAll: function () { Object.keys(state.stitches).forEach(function (id) { state.stitches[id].state = 'open'; state.stitches[id].t = 1; }); },
        forceFail: function () { failAt = state.time; },
        forceFinish: function (loopFirst) {
          this.setHeld('purl', 3); this.setHeld('loop', 3);
          if (loopFirst) { state.loop.finishTime = Math.max(0, state.time - 2.4); state.loop.rank = 1; state.loop.action = 'finished'; }
          const fi = route.length - 1;
          this.teleport('purl', route[fi].id, segInfo[fi].finish - 0.001);
          if (!loopFirst) this.teleport('loop', loopRoute[fi].id, 0.2);
        },
        message: function (text, kind) { say(text, kind, 3); },
        scenario: SCENARIO
      }
    };
  }

  /* ---------------- fake renderer ---------------- */

  function createRenderer(opts) {
    const canvas = opts.canvas;
    const ctx = canvas.getContext('2d');
    const images = opts.images || {};
    const level = opts.level || WW.LEVEL;
    const plates = opts.plates || WW.PLATES || {};
    const D = WW.DESIGN || { w: 841, h: 1870 };
    let W = 1, H = 1, dpr = 1;
    let view = { x: 0, y: 0, w: 1, h: 1, s: 1 };
    let currentPlate = 'p01';
    let targets = [];
    const callouts = [];
    let clockT = 0;

    function resize(w, h, ratio) {
      W = w; H = h; dpr = Math.min(2, ratio || 1);
      canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
      const s = Math.min(w / D.w, h / D.h);
      view = { x: (w - D.w * s) / 2, y: (h - D.h * s) / 2, w: D.w * s, h: D.h * s, s: s };
    }

    function plateFor(state) {
      const seg = level.route[state.purl.seg] || level.route[0];
      if (seg.kind === 'plate') return seg.plate;
      return (state.purl.f < 0.5 ? seg.from : seg.to) || 'p01';
    }

    function worldToScreen(plateId, x, y) { return { x: view.x + x * view.s, y: view.y + y * view.s }; }

    function render(state, dt) {
      clockT += dt || 0;
      currentPlate = plateFor(state);
      const img = images[currentPlate];
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = '#2a1810';
      ctx.fillRect(0, 0, W, H);
      if (img) {
        // framing: cover-fit, darkened (stand-in for the real renderer's blurred copy)
        const cs = Math.max(W / D.w, H / D.h);
        ctx.globalAlpha = 0.35;
        ctx.drawImage(img, (W - D.w * cs) / 2, (H - D.h * cs) / 2, D.w * cs, D.h * cs);
        ctx.globalAlpha = 1;
        ctx.drawImage(img, view.x, view.y, view.w, view.h);
      }
      const seg = level.route[state.purl.seg] || {};
      // stitch target
      targets = [];
      const stitchId = Object.keys(state.stitches || {}).find(function (id) {
        return state.stitches[id].state === 'ready' && level.stitches[id] && level.stitches[id].seg === seg.id;
      });
      if (stitchId) {
        const sd = (plates[currentPlate] && plates[currentPlate].stitch) || { x: 560, y: 1380, r: 70 };
        const p = worldToScreen(currentPlate, sd.x, sd.y);
        const r = Math.max(44, sd.r * view.s);
        targets.push({ id: stitchId, x: p.x, y: p.y, r: r });
        const pulse = 1 + 0.12 * Math.sin(clockT * 6);
        ctx.strokeStyle = 'rgba(255, 214, 92, 0.95)'; ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(p.x, p.y, r * 0.7 * pulse, 0, Math.PI * 2); ctx.stroke();
        ctx.font = '700 14px sans-serif'; ctx.textAlign = 'center';
        ctx.fillStyle = '#fff8e8'; ctx.fillRect(p.x - 52, p.y - r - 30, 104, 24);
        ctx.fillStyle = '#552916'; ctx.fillText('Tap the stitch', p.x, p.y - r - 13);
      }
      // dropped items
      Object.keys(state.items || {}).forEach(function (k) {
        const it = state.items[k];
        if (it.owner !== 'purl' || it.status !== 'dropped' || it.seg !== seg.id) return;
        const dfx = it.f - state.purl.f;
        const x = W / 2 + it.lane * W * 0.22, y = H * 0.8 - dfx * H * 2.2;
        ctx.fillStyle = '#18a3ad'; ctx.beginPath(); ctx.arc(x, y, 12, 0, Math.PI * 2); ctx.fill();
      });
      // Loop (teal circle) when on the same segment index
      if (state.loop && state.loop.seg === state.purl.seg && seg.kind === 'plate') {
        const dfl = state.loop.f - state.purl.f;
        const x = W * 0.72, y = clamp(H * 0.78 - dfl * H * 1.6, H * 0.3, H * 0.95);
        ctx.fillStyle = '#0b97a3'; ctx.beginPath(); ctx.arc(x, y, 22, 0, Math.PI * 2); ctx.fill();
      }
      // Purl (coral circle)
      const px = W / 2 + (state.purl.laneX || 0) * W * 0.22;
      const py = H * 0.8 - (state.purl.jumpH || 0) * H * 0.08;
      ctx.fillStyle = 'rgba(40,20,10,.35)'; ctx.beginPath(); ctx.ellipse(px, H * 0.8 + 30, 34, 9, 0, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = state.purl.action === 'tangled' ? '#a31b3c' : '#e8414f';
      ctx.beginPath(); ctx.arc(px, py, 34, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#fff3d6'; ctx.lineWidth = 3; ctx.stroke();
      // snagling
      if (seg.id === 'landing' && state.snagling && (state.snagling.state === 'hop' || state.snagling.state === 'tangle')) {
        ctx.fillStyle = '#7a1f4f'; ctx.beginPath(); ctx.arc(W * 0.22, H * 0.7, 26, 0, Math.PI * 2); ctx.fill();
      }
      // callouts
      for (let i = callouts.length - 1; i >= 0; i--) {
        const c = callouts[i];
        c.t += dt || 0;
        if (c.t > 1.2) { callouts.splice(i, 1); continue; }
        ctx.globalAlpha = 1 - c.t / 1.2;
        ctx.font = '900 18px sans-serif'; ctx.textAlign = 'center';
        ctx.fillStyle = c.good ? '#fff8e8' : '#ffdfe6';
        ctx.fillText(c.text, W * 0.66, H * 0.62 - c.t * 30);
        ctx.globalAlpha = 1;
      }
      if (opts.debug) {
        ctx.fillStyle = 'rgba(0,0,0,.6)'; ctx.fillRect(0, H - 22, W, 22);
        ctx.fillStyle = '#fff'; ctx.font = '11px monospace'; ctx.textAlign = 'left';
        ctx.fillText('STUB ' + seg.id + ' f=' + state.purl.f.toFixed(3) + ' t=' + (state.time || 0).toFixed(2) + ' ' + state.mode, 6, H - 7);
      }
    }

    function handleEvents(events) {
      events.forEach(function (e) {
        if (e.type === 'pickup' && String(e.item).indexOf('purl.') === 0) callouts.push({ text: '+1 THREAD', good: true, t: 0 });
        if (e.type === 'recover') callouts.push({ text: '+1 THREAD', good: true, t: 0 });
        if (e.type === 'drop') callouts.push({ text: '−1 THREAD', good: false, t: 0 });
      });
    }

    return {
      resize: resize, render: render, handleEvents: handleEvents, worldToScreen: worldToScreen,
      getTapTargets: function () { return targets.slice(); },
      getLayout: function () { return { view: { x: view.x, y: view.y, w: view.w, h: view.h }, purl: { x: W / 2, y: H * 0.8, w: 68 } }; },
      isStub: true
    };
  }

  WW.sim = Object.assign({}, WW.sim, { createRace: createRace, isStub: true });
  WW.render = Object.assign({}, WW.render, { createRenderer: createRenderer, isStub: true });
})(globalThis.WW = globalThis.WW || {});

input.content:
/* Wishweave Wonders — Level 1 UI.
   The HUD reproduces the approved cream stitched pills (assets/ui/pill.webp as a 9-slice border image), brown text,
   coral PURL / teal LOOP labels with gold star icons, the round stitched pause button, the WISHWEAVE WONDERS logo,
   the slim SAVED REWARDS strip and (07) LEVEL 1 COMPLETE + rank pills + PLAY AGAIN.
   Geometry is measured from the approved 841 × 1870 PNGs in design px and scaled by --k (CSS px per design px, set
   by main.js from the game width), with legibility / touch minimums. Approved reference (design px):
     logo 384 wide, top 22 · pause centre (785, 76) Ø75 · LEVEL pill centre y 186 · PURL/LOOP pills 222 wide, y 241 ·
     objective pill 365 wide, y 298 · results title y 314, ranks y 368 · PLAY AGAIN 392 × 94, bottom 143 ·
     rewards strip 746 × 80, bottom 51 (track 171 × 30, slots Ø35, CASH OUT 191 × 47). */

:root {
  --brown: #552916;
  --brown-2: #5b2a14;
  --coral: #c51640;
  --coral-bright: #f24c7d;
  --teal: #067e8d;
  --teal-bright: #03a7ae;
  --teal-deep: #007685;
  --cream: #fff8e8;
  --cream-2: #f8e6ca;
  --stitch: #d6a24a;
  --gold: #f2b83a;
  --grey: #aaa398;
  color-scheme: light;
}

* { box-sizing: border-box; }

html, body {
  margin: 0; height: 100%; overflow: hidden;
  background: #2b1810;
  font-family: "Nunito", "Baloo 2", "Fredoka", "Trebuchet MS", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-synthesis: none;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  overscroll-behavior: none;
}

button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; }

[hidden] { display: none !important; }

/* #app is the safe content rectangle: the viewport minus env(safe-area-inset-*). Inside the Android host the
   WebView is already padded by the system-bar/cutout insets, so env() reads 0 there and nothing is counted twice. */
#app {
  position: fixed; inset: 0;
  padding: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px)
           env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);
  display: flex; align-items: center; justify-content: center;
  background:
    radial-gradient(ellipse at 50% 30%, rgba(255, 196, 120, .16), rgba(0, 0, 0, 0) 60%),
    repeating-linear-gradient(45deg, rgba(255, 230, 190, .035) 0 6px, rgba(0, 0, 0, 0) 6px 12px),
    linear-gradient(180deg, #4a2a1a, #23130c);
}

/* The play area. main.js sizes it (px) and sets --k: full safe width on phones, a centred portrait column on
   wide/landscape screens. */
#game {
  --k: 0.49;
  --edge: max(6px, calc(var(--k) * 16px));
  --rw-h: max(34px, calc(var(--k) * 80px));
  --rw-bottom: max(6px, calc(var(--k) * 51px));
  position: relative;
  flex: none;
  width: 100%; height: 100%;
  overflow: hidden;
  background: #1d120c;
  touch-action: none;
  user-select: none; -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  contain: layout paint;
}
#game.is-column { box-shadow: 0 0 0 1px rgba(255, 226, 170, .18), 0 0 40px rgba(0, 0, 0, .55); }

#view { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

/* Soft red edge flash when Snagling lands a hit (the renderer draws the tangle itself). */
#game.fx-hit::after {
  content: ""; position: absolute; inset: 0; z-index: 6; pointer-events: none;
  box-shadow: inset 0 0 calc(var(--k) * 140px) rgba(214, 34, 74, .55);
  animation: hitflash .6s ease-out forwards;
}
@keyframes hitflash { 0% { opacity: 0; } 15% { opacity: 1; } 100% { opacity: 0; } }

/* ---------- Stitched cream pill (9-slice of assets/ui/pill.webp, 798×193, caps ≈ 96 px) ---------- */
.pill {
  --ph: 2.05em;
  display: inline-flex; align-items: center; justify-content: center;
  height: var(--ph);
  padding: 0 1.15em;
  border: 0 solid transparent;
  border-image-source: url("assets/ui/pill.webp");
  border-image-slice: 96 100 fill;
  border-image-width: calc(var(--ph) / 2) calc(var(--ph) * .53);
  border-image-repeat: stretch;
  color: var(--brown);
  font-weight: 800;
  letter-spacing: .02em;
  white-space: nowrap;
  line-height: 1;
  filter: drop-shadow(0 .1em .16em rgba(75, 35, 28, .38));
  margin: 0;
}

/* ---------- HUD ---------- */
.hud {
  position: absolute; left: 0; right: 0; top: 0;
  padding-top: max(4px, calc(var(--k) * 22px));
  display: flex; flex-direction: column; align-items: center;
  pointer-events: none;
  z-index: 10;
}
.hud-logo {
  display: block;
  width: calc(var(--k) * 384px); height: calc(var(--k) * 137.4px);
  filter: drop-shadow(0 calc(var(--k) * 5px) calc(var(--k) * 7px) rgba(60, 25, 10, .45));
  pointer-events: none;
}
#game.no-logo .hud-logo { display: none; }
#game.no-logo .hud { padding-top: max(6px, calc(var(--k) * 16px)); }

.hud-phase {
  font-size: max(11px, calc(var(--k) * 27px));
  --ph: 1.89em;
  margin-top: calc(var(--k) * 1px);
  min-width: calc(var(--k) * 200px);
  padding: 0 1.3em;
}

.hud-counts { display: flex; gap: max(5px, calc(var(--k) * 13px)); margin-top: calc(var(--k) * 1px); }
.hud-count {
  position: relative;
  font-size: max(11px, calc(var(--k) * 24px));
  --ph: 2.375em;
  width: max(9.2em, calc(var(--k) * 222px));
  justify-content: space-between;
  padding: 0 1.12em 0 2.62em;
  transform-origin: 50% 50%;
}
.hud-count .star {
  position: absolute; left: .02em; top: 50%; width: 2.1em; height: 2.1em; transform: translateY(-50%);
  filter: drop-shadow(0 .05em .05em rgba(90, 45, 10, .4));
}
.hud-count .who { font-size: .92em; letter-spacing: .03em; }
.hud-count.purl .who { color: var(--coral); }
.hud-count.loop .who { color: var(--teal); }
.hud-count .num { font-size: 1.08em; font-variant-numeric: tabular-nums; white-space: pre; }
.hud-count .num b { font-weight: 800; }
.hud-count.up { animation: pop .55s cubic-bezier(.2, 1.6, .4, 1); }
.hud-count.down { animation: shake .6s ease-in-out; }
@keyframes pop {
  0% { transform: scale(1); }
  35% { transform: scale(1.16); filter: drop-shadow(0 0 .5em rgba(255, 210, 90, .95)); }
  100% { transform: scale(1); }
}
@keyframes shake {
  0%, 100% { transform: translateX(0); color: var(--brown); }
  15% { transform: translateX(-.35em) rotate(-2deg); color: #b52248; }
  35% { transform: translateX(.3em) rotate(2deg); color: #b52248; }
  55% { transform: translateX(-.22em); color: #b52248; }
  75% { transform: translateX(.12em); }
}

.hud-objective {
  position: relative;
  font-size: max(10.5px, calc(var(--k) * 22px));
  --ph: 2.36em;
  margin-top: calc(var(--k) * 2.5px);
  min-width: max(15.5em, calc(var(--k) * 365px));
  max-width: calc(100% - 2 * var(--edge));
  padding: 0 3.3em 0 1.9em;
}
.hud-objective .txt { overflow: hidden; text-overflow: ellipsis; display: inline-block; }
.hud-objective .flag { position: absolute; right: .3em; top: 50%; width: 2.2em; height: 2.2em; transform: translateY(-52%); }
.hud-objective.is-message .txt { animation: msgIn .35s ease-out; }
.hud-objective.kind-hit .txt { color: #8e1d35; }
.hud-objective.kind-recover .txt { color: #0b6f62; }
@keyframes msgIn { from { transform: scale(.85); opacity: .2; } to { transform: scale(1); opacity: 1; } }

/* Slim race-progress thread: coral bead = Purl, teal bead = Loop (computer rival). */
.race-thread {
  position: relative;
  width: max(150px, calc(var(--k) * 330px));
  height: 10px;
  margin-top: max(3px, calc(var(--k) * 7px));
}
.race-thread::before {
  content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 3px; transform: translateY(-50%);
  border-radius: 2px;
  background: repeating-linear-gradient(90deg, #f6d888 0 5px, #c48a2c 5px 7px);
  box-shadow: 0 0 0 1px rgba(255, 248, 228, .85), 0 1px 3px rgba(60, 25, 10, .5);
}
.race-thread::after {
  content: ""; position: absolute; right: -4px; top: 50%; width: 8px; height: 8px; transform: translateY(-50%) rotate(45deg);
  background: var(--gold); border: 1.5px solid #fff3d2; border-radius: 2px;
}
.race-thread .bead {
  position: absolute; top: 50%; left: 0; width: 10px; height: 10px; margin: -5px 0 0 -5px;
  border-radius: 50%; border: 1.5px solid #fff6df;
  box-shadow: 0 1px 2px rgba(50, 20, 10, .55);
}
.race-thread .bead.purl { background: radial-gradient(circle at 35% 35%, #ff8d99, #e0344f 70%); z-index: 2; }
.race-thread .bead.loop { background: radial-gradient(circle at 35% 35%, #6fe0e2, #0b97a3 70%); width: 9px; height: 9px; margin: -4.5px 0 0 -4.5px; }

.hud-hint {
  margin-top: max(4px, calc(var(--k) * 10px));
  max-width: calc(100% - 4 * var(--edge));
  padding: .45em 1em;
  border-radius: 1.2em;
  background: linear-gradient(#fff8e8, #f6e3c4);
  border: 1.5px solid #fff6df;
  box-shadow: 0 0 0 1px #c7a480 inset, 0 2px 6px rgba(60, 25, 10, .35);
  color: var(--brown);
  font-size: max(11px, calc(var(--k) * 21px));
  font-weight: 700;
  text-align: center;
  line-height: 1.25;
  animation: msgIn .3s ease-out;
}

/* Results (approved 07): LEVEL 1 COMPLETE with flower ends, true ranks, times. */
.hud-results { display: flex; flex-direction: column; align-items: center; }
.result-title {
  position: relative;
  font-size: max(15px, calc(var(--k) * 34px));
  --ph: 1.7em;
  margin-top: calc(var(--k) * 15.5px);
  min-width: max(11em, calc(var(--k) * 361px));
  padding: 0 1.5em;
  letter-spacing: .03em;
}
.result-title .orn, .btn-play-again .orn {
  position: absolute; top: 50%; width: 1.5em; height: 1.5em; transform: translateY(-50%); z-index: 2;
  filter: drop-shadow(0 .05em .06em rgba(90, 45, 10, .45));
}
.result-title .orn.l { left: -.62em; } .result-title .orn.r { right: -.62em; }
.result-ranks, .result-times { gap: .45em; padding: 0 1.4em; }
.result-ranks {
  font-size: max(11.5px, calc(var(--k) * 24px));
  --ph: 1.71em;
  margin-top: calc(var(--k) * 4.5px);
  min-width: max(13em, calc(var(--k) * 307px));
}
.result-times {
  font-size: max(10.5px, calc(var(--k) * 19px));
  --ph: 1.9em;
  margin-top: calc(var(--k) * 6px);
  min-width: max(13em, calc(var(--k) * 290px));
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.result-ranks .p, .result-times .p { color: var(--coral); }
.result-ranks .l, .result-times .l { color: var(--teal); }
.result-ranks .dot, .result-times .dot { color: var(--brown); opacity: .75; }
.result-wait {
  margin-top: max(4px, calc(var(--k) * 8px));
  font-size: max(11px, calc(var(--k) * 21px)); font-weight: 800; color: #fff8e5;
  padding: .3em .9em; border-radius: 1em;
  background: rgba(0, 105, 118, .86);
  box-shadow: 0 0 0 1.5px #83dfd1 inset, 0 2px 6px rgba(0, 40, 45, .4);
}
.result-wait .dots i { font-style: normal; animation: blink 1.2s infinite; }
.result-wait .dots i:nth-child(2) { animation-delay: .2s; } .result-wait .dots i:nth-child(3) { animation-delay: .4s; }
@keyframes blink { 0%, 100% { opacity: .2; } 40% { opacity: 1; } }

/* Round stitched pause button, top-right. The image matches the approved size (Ø75 design px); the button itself
   is never smaller than 48 CSS px so it stays an easy touch target. */
.btn-pause {
  --pv: max(34px, calc(var(--k) * 75.5px));
  --hit: max(48px, var(--pv));
  position: absolute; z-index: 30;
  top: max(0px, calc(var(--k) * 76px - var(--hit) / 2));
  right: max(0px, calc(var(--k) * 55.5px - var(--hit) / 2));
  width: var(--hit); height: var(--hit);
  padding: 0; border: 0; border-radius: 50%;
  background: url("assets/ui/pause.webp") center / var(--pv) var(--pv) no-repeat;
  filter: drop-shadow(0 2px 3px rgba(60, 25, 10, .45));
  cursor: pointer; touch-action: manipulation;
}
.btn-pause:active { transform: scale(.93); }
#game.no-logo .btn-pause { top: max(0px, calc(max(6px, var(--k) * 16px) + max(11px, var(--k) * 27px) * .945 - var(--hit) / 2)); }

/* ---------- Buttons ---------- */
.btn-teal, .btn-cream {
  position: relative;
  display: flex; align-items: center; justify-content: center;
  min-height: 48px; min-width: 44px;
  border: 0 solid transparent;
  border-image-source: url("assets/ui/pill.webp");
  border-image-slice: 96 100 fill;
  border-image-repeat: stretch;
  background: none;
  font-weight: 900; letter-spacing: .04em;
  cursor: pointer; touch-action: manipulation;
  filter: drop-shadow(0 3px 4px rgba(60, 25, 10, .42));
}
.btn-teal { --bh: 52px; height: var(--bh); border-image-width: calc(var(--bh) / 2) calc(var(--bh) * .53); padding: 0; }
.btn-teal .face {
  position: absolute; inset: 12% 5% 14% 5%;
  display: flex; align-items: center; justify-content: center;
  border-radius: 999px;
  background:
    repeating-linear-gradient(100deg, rgba(255, 255, 255, .05) 0 3px, rgba(0, 0, 0, .04) 3px 6px),
    linear-gradient(180deg, #19b8bd 0%, var(--teal-bright) 35%, var(--teal-deep) 100%);
  box-shadow: inset 0 0 0 2px #83dfd1, inset 0 2px 0 rgba(255, 255, 255, .35), inset 0 -3px 4px rgba(0, 60, 70, .35);
  color: #fff8e5;
  font-size: 1.12em;
  text-shadow: 0 2px 0 rgba(0, 70, 80, .55);
}
.btn-cream { --bh: 48px; height: var(--bh); border-image-width: calc(var(--bh) / 2) calc(var(--bh) * .53); padding: 0 1.6em; color: var(--brown); font-size: 1em; }
.btn-teal:active, .btn-cream:active { transform: translateY(1px) scale(.98); }
.btn-teal:focus-visible, .btn-cream:focus-visible, .btn-pause:focus-visible, .btn-cashout:focus-visible { outline: 3px solid #ffd45c; outline-offset: 3px; }
.btn-wide { width: 100%; max-width: 290px; margin-left: auto; margin-right: auto; }

/* PLAY AGAIN (approved 07), just above the rewards strip. */
.btn-play-again {
  --bh: max(56px, calc(var(--k) * 94px));
  position: absolute; z-index: 30; left: 50%; transform: translateX(-50%);
  bottom: calc(var(--rw-bottom) + var(--rw-h) + max(6px, calc(var(--k) * 12px)));
  width: max(236px, calc(var(--k) * 392px));
  font-size: max(17px, calc(var(--k) * 34px));
  animation: rise .45s cubic-bezier(.2, 1.4, .4, 1);
}
.btn-play-again .face { font-size: 1em; }
.btn-play-again:active { transform: translateX(-50%) translateY(1px) scale(.98); }
.btn-play-again .orn { width: 1.55em; height: 1.55em; }
.btn-play-again .orn.l { left: -.5em; } .btn-play-again .orn.r { right: -.5em; }
@keyframes rise { from { transform: translateX(-50%) translateY(30px); opacity: 0; } to { transform: translateX(-50%); opacity: 1; } }

/* ---------- Saved rewards strip (placeholder only; locked cash out) ---------- */
.rewards {
  position: absolute; z-index: 20; left: 50%; transform: translateX(-50%);
  bottom: var(--rw-bottom);
  width: min(calc(100% - 2 * max(4px, calc(var(--k) * 30px))), max(300px, calc(var(--k) * 746px)));
  height: var(--rw-h);
  display: flex; align-items: center;
  padding: 0 calc(var(--k) * 35px) 0 max(10px, calc(var(--k) * 43px));
  border: 0 solid transparent;
  border-image-source: url("assets/ui/pill.webp");
  border-image-slice: 96 100 fill;
  border-image-width: calc(var(--rw-h) / 2) calc(var(--rw-h) * .53);
  filter: drop-shadow(0 2px 4px rgba(60, 25, 10, .4));
  font-size: max(9px, calc(var(--k) * 18px));
  pointer-events: none;
}
.rw-label { flex: none; color: var(--brown-2); font-weight: 900; letter-spacing: .005em; white-space: nowrap; }
.rw-bar {
  position: relative; flex: 0 1 calc(var(--k) * 171px); min-width: 26px;
  margin-left: max(5px, calc(var(--k) * 21px));
  height: max(14px, calc(var(--k) * 30px)); border-radius: 999px; background: #ecd8bf;
  box-shadow: inset 0 1px 2px rgba(120, 70, 30, .22);
}
.rw-bar i {
  position: absolute; left: 1%; top: 10%; bottom: 10%; width: 52%; border-radius: 999px;
  background: linear-gradient(180deg, #ff7c9d, var(--coral-bright) 50%, #d93466);
  box-shadow: inset 0 0 0 1.5px #ff9db0, inset 0 -2px 2px rgba(150, 20, 60, .25);
}
.rw-slot {
  flex: none; width: max(14px, calc(var(--k) * 35px)); height: max(14px, calc(var(--k) * 35px));
  margin-left: max(5px, calc(var(--k) * 22px));
  border-radius: 50%; background: #ecd8bf; box-shadow: inset 0 1px 2px rgba(120, 70, 30, .2);
}
.btn-cashout {
  position: relative; flex: none; margin-left: auto;
  display: inline-flex; align-items: center; justify-content: center; gap: .45em;
  height: max(22px, calc(var(--k) * 47px)); min-width: max(84px, calc(var(--k) * 191px));
  padding: 0 .9em 0 .7em;
  border-radius: 999px;
  border: 1.5px solid #d4ccbf;
  background: linear-gradient(180deg, #a49d92, #8d867c);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .25), 0 1px 2px rgba(60, 40, 20, .25);
  color: #fffaf0; font-weight: 700; font-size: 1.12em; letter-spacing: .03em;
  white-space: nowrap;
  cursor: not-allowed; pointer-events: auto; touch-action: manipulation;
}
/* Enlarge the touch target to ≥ 44 px without changing the approved slim look. */
.btn-cashout::after { content: ""; position: absolute; left: -6px; right: -6px; top: 50%; height: 48px; transform: translateY(-50%); }
.btn-cashout .lock { width: 1.2em; height: 1.2em; color: #fffaf0; flex: none; }

.note {
  position: absolute; z-index: 40; right: max(8px, calc(var(--k) * 40px));
  bottom: calc(var(--rw-bottom) + var(--rw-h) + 10px);
  max-width: min(80%, 300px);
  padding: .7em 1em; border-radius: 14px;
  background: linear-gradient(#fff8e8, #f6e3c4);
  border: 1.5px solid #fff6df;
  box-shadow: 0 0 0 1px #c7a480 inset, 0 4px 10px rgba(50, 20, 10, .4);
  color: var(--brown); font-size: 12.5px; font-weight: 700; line-height: 1.35;
  pointer-events: none;
}
.note.in { animation: noteIn .25s ease-out; }
.note::after { content: ""; position: absolute; right: 22%; bottom: -7px; width: 12px; height: 12px; background: #f6e3c4; transform: rotate(45deg); box-shadow: 1px 1px 0 #c7a480; }
@keyframes noteIn { from { transform: translateY(6px); opacity: 0; } to { transform: none; opacity: 1; } }

/* ---------- Countdown ---------- */
.countdown {
  position: absolute; z-index: 25; left: 0; right: 0; top: 34%;
  display: flex; justify-content: center; pointer-events: none;
}
.countdown span {
  display: block;
  font-size: max(72px, calc(var(--k) * 230px)); line-height: 1; font-weight: 900;
  color: #ff5a72;
  -webkit-text-stroke: max(4px, calc(var(--k) * 12px)) #fff3d6;
  paint-order: stroke fill;
  text-shadow: 0 calc(var(--k) * 10px) 0 rgba(120, 30, 40, .55), 0 0 30px rgba(255, 210, 120, .6);
}
.countdown span.tick { animation: count .9s ease-out both; }
.countdown.go span { color: #12b2b8; text-shadow: 0 calc(var(--k) * 10px) 0 rgba(0, 80, 90, .55), 0 0 30px rgba(255, 230, 150, .7); }
.countdown.go span.tick { animation-duration: .8s; }
@keyframes count { 0% { transform: scale(1.6); opacity: 0; } 18% { transform: scale(1); opacity: 1; } 78% { opacity: 1; } 100% { transform: scale(.85); opacity: 0; } }

/* ---------- Overlays ---------- */
.overlay {
  position: absolute; inset: 0; z-index: 50;
  display: flex; align-items: center; justify-content: center;
  padding: max(10px, calc(var(--k) * 30px)) max(10px, calc(var(--k) * 30px));
  background: radial-gradient(ellipse at 50% 45%, rgba(45, 22, 12, .28), rgba(28, 12, 6, .66));
  overflow-y: auto; overscroll-behavior: contain;
  touch-action: pan-y;
  animation: fade .25s ease-out;
}
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
.card {
  position: relative;
  width: 100%; max-width: 360px; margin: auto;
  padding: 18px 18px 16px;
  border-radius: 26px;
  background: linear-gradient(180deg, #fff9ec, #f6e2c2);
  box-shadow: 0 0 0 3px #fff6df, 0 0 0 4.5px #d7b48b, 0 14px 34px rgba(30, 10, 4, .55);
  color: var(--brown);
  text-align: center;
  font-size: 14px;
}
.card::before {
  content: ""; position: absolute; inset: 7px; border-radius: 20px;
  border: 2px dashed rgba(214, 162, 74, .85);
  pointer-events: none;
}
.card > * { position: relative; }
.ov-logo { display: block; width: 86%; max-width: 300px; height: auto; margin: -6px auto 4px; filter: drop-shadow(0 4px 5px rgba(60, 25, 10, .35)); }
.title-pill { font-size: 16px; margin: 2px auto 8px; padding: 0 1.4em; }
.card .sub { margin: 4px 6px 14px; font-size: 14px; line-height: 1.4; font-weight: 600; color: #6b3a20; }
.card .fine { margin: 10px 4px 0; font-size: 11.5px; line-height: 1.35; color: #8a5a3a; font-weight: 600; }
.card .btn-wide + .btn-wide { margin-top: 10px; }

.ov-loading { background: radial-gradient(ellipse at 50% 40%, #5b3420, #24130b); }
.load-bar { height: 16px; margin: 8px 12px 6px; border-radius: 999px; background: #e8ceb2; box-shadow: inset 0 1px 3px rgba(110, 60, 20, .35); overflow: hidden; }
.load-bar i { display: block; height: 100%; width: 0; border-radius: 999px; background: linear-gradient(180deg, #ff7c9d, #f24c7d 55%, #d93466); transition: width .2s; }
.load-text { margin: 6px 0 2px; font-size: 13px; font-weight: 700; color: #7b4a2a; }
#btn-load-retry { margin: 12px auto 0; }

.versus { display: flex; align-items: flex-end; justify-content: center; gap: 4px; margin: 0 0 2px; }
.racer { margin: 0; display: flex; flex-direction: column; align-items: center; }
.racer canvas { width: 104px; height: 104px; display: block; filter: drop-shadow(0 4px 4px rgba(60, 25, 10, .35)); }
.racer figcaption { margin-top: -2px; line-height: 1.05; }
.racer figcaption b { display: block; font-size: 16px; font-weight: 900; letter-spacing: .04em; }
.racer figcaption small { font-size: 11px; font-weight: 700; color: #8a5a3a; }
.racer.purl b { color: var(--coral); } .racer.loop b { color: var(--teal); }
.vs { align-self: center; margin: 0 2px 26px; font-size: 18px; font-weight: 900; color: #fff; -webkit-text-stroke: 4px #b07a2c; paint-order: stroke fill; }
.rival-note { margin: 2px 0 8px; font-size: 13px; font-weight: 800; color: var(--teal); }

.howto { list-style: none; margin: 0 0 14px; padding: 0; text-align: left; display: grid; gap: 6px; }
.howto li { display: flex; align-items: center; gap: 10px; font-size: 13.5px; line-height: 1.25; font-weight: 600; color: #5d2f17; }
.howto b { font-weight: 900; color: var(--brown); }
.howto .ico {
  flex: none; width: 34px; height: 34px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: radial-gradient(circle at 40% 35%, #fffdf6, #f1dcb8);
  box-shadow: 0 0 0 2px #fff6df, 0 0 0 3px #d7b48b;
  font-weight: 900; font-size: 17px; color: #7a4320;
}
.howto .ico svg { width: 24px; height: 24px; }
.ico-tap { position: relative; }
.ico-tap::before { content: ""; width: 12px; height: 12px; border-radius: 50%; background: #ffd45c; box-shadow: 0 0 0 3px rgba(242, 184, 58, .45), 0 0 8px 3px rgba(255, 200, 80, .8); }
.ico-lr { font-size: 14px !important; letter-spacing: -1px; }

.ov-fail .card { max-width: 340px; }
#fail-purl { width: 110px; height: 110px; display: block; margin: -4px auto 0; filter: drop-shadow(0 4px 4px rgba(60, 25, 10, .35)); }

.ov-error .card { max-width: 340px; }

/* ---------- Compact layouts (classes set by main.js from the measured game size) ---------- */
#game.is-short .card { padding: 14px 14px 12px; }
#game.is-short .ov-logo { width: 70%; max-width: 230px; margin-top: -4px; }
#game.is-short .racer canvas { width: 82px; height: 82px; }
#game.is-short .howto { gap: 4px; margin-bottom: 10px; }
#game.is-short .howto li { font-size: 12.5px; }
#game.is-short .howto .ico { width: 28px; height: 28px; font-size: 15px; }
#game.is-short .howto .ico svg { width: 20px; height: 20px; }

#game.is-tiny .card { padding: 10px 12px; font-size: 13px; }
#game.is-tiny .ov-logo { display: none; }
#game.is-tiny .racer canvas { width: 60px; height: 60px; }
#game.is-tiny .racer figcaption b { font-size: 13px; }
#game.is-tiny .rival-note { margin: 0 0 4px; font-size: 12px; }
#game.is-tiny .howto li { font-size: 11.5px; }
#game.is-tiny .howto .ico { width: 24px; height: 24px; font-size: 13px; box-shadow: 0 0 0 1.5px #fff6df, 0 0 0 2.5px #d7b48b; }
#game.is-tiny .howto .ico svg { width: 17px; height: 17px; }
#game.is-tiny .ico-tap::before { width: 9px; height: 9px; }
#game.is-tiny .card .fine { margin-top: 6px; font-size: 10.5px; }
#game.is-tiny .card .sub { margin-bottom: 8px; font-size: 12.5px; }
#game.is-tiny .btn-teal { --bh: 48px; }
#game.is-tiny .btn-cream { --bh: 44px; }
#game.is-tiny .card .btn-wide + .btn-wide { margin-top: 6px; }
#game.is-tiny #fail-purl { width: 72px; height: 72px; }
#game.is-tiny .title-pill { font-size: 14px; margin-bottom: 4px; }
#game.is-tiny .race-thread { display: none; }
#game.is-tiny .hud-phase { display: none; }
#game.is-tiny .btn-pause { top: max(0px, calc(max(6px, var(--k) * 16px) + max(11px, var(--k) * 24px) * 1.19 - var(--hit) / 2)); }
#game.is-tiny .countdown { top: 28%; }
#game.is-tiny .countdown span { font-size: 64px; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition: none !important; }
}

toolu_01CyEiw3RhMv9Bgy3dtPPLqV.content:
/* Wishweave Wonders — Level 1 UI.
   The HUD reproduces the approved cream stitched pills (assets/ui/pill.webp as a 9-slice border image), brown text,
   coral PURL / teal LOOP labels with gold star icons, the round stitched pause button, the WISHWEAVE WONDERS logo,
   the slim SAVED REWARDS strip and (07) LEVEL 1 COMPLETE + rank pills + PLAY AGAIN.
   Geometry is measured from the approved 841 × 1870 PNGs in design px and scaled by --k (CSS px per design px, set
   by main.js from the game width), with legibility / touch minimums. Approved reference (design px):
     logo 384 wide, top 22 · pause centre (785, 76) Ø75 · LEVEL pill centre y 186 · PURL/LOOP pills 222 wide, y 241 ·
     objective pill 365 wide, y 298 · results title y 314, ranks y 368 · PLAY AGAIN 392 × 94, bottom 143 ·
     rewards strip 746 × 80, bottom 51 (track 171 × 30, slots Ø35, CASH OUT 191 × 47). */

:root {
  --brown: #552916;
  --brown-2: #5b2a14;
  --coral: #c51640;
  --coral-bright: #f24c7d;
  --teal: #067e8d;
  --teal-bright: #03a7ae;
  --teal-deep: #007685;
  --cream: #fff8e8;
  --cream-2: #f8e6ca;
  --stitch: #d6a24a;
  --gold: #f2b83a;
  --grey: #aaa398;
  color-scheme: light;
}

* { box-sizing: border-box; }

html, body {
  margin: 0; height: 100%; overflow: hidden;
  background: #2b1810;
  font-family: "Nunito", "Baloo 2", "Fredoka", "Trebuchet MS", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-synthesis: none;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  overscroll-behavior: none;
}

button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; }

[hidden] { display: none !important; }

/* #app is the safe content rectangle: the viewport minus env(safe-area-inset-*). Inside the Android host the
   WebView is already padded by the system-bar/cutout insets, so env() reads 0 there and nothing is counted twice. */
#app {
  position: fixed; inset: 0;
  padding: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px)
           env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);
  display: flex; align-items: center; justify-content: center;
  background:
    radial-gradient(ellipse at 50% 30%, rgba(255, 196, 120, .16), rgba(0, 0, 0, 0) 60%),
    repeating-linear-gradient(45deg, rgba(255, 230, 190, .035) 0 6px, rgba(0, 0, 0, 0) 6px 12px),
    linear-gradient(180deg, #4a2a1a, #23130c);
}

/* The play area. main.js sizes it (px) and sets --k: full safe width on phones, a centred portrait column on
   wide/landscape screens. */
#game {
  --k: 0.49;
  --edge: max(6px, calc(var(--k) * 16px));
  --rw-h: max(34px, calc(var(--k) * 80px));
  --rw-bottom: max(6px, calc(var(--k) * 51px));
  position: relative;
  flex: none;
  width: 100%; height: 100%;
  overflow: hidden;
  background: #1d120c;
  touch-action: none;
  user-select: none; -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  contain: layout paint;
}
#game.is-column { box-shadow: 0 0 0 1px rgba(255, 226, 170, .18), 0 0 40px rgba(0, 0, 0, .55); }

#view { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

/* Soft red edge flash when Snagling lands a hit (the renderer draws the tangle itself). */
#game.fx-hit::after {
  content: ""; position: absolute; inset: 0; z-index: 6; pointer-events: none;
  box-shadow: inset 0 0 calc(var(--k) * 140px) rgba(214, 34, 74, .55);
  animation: hitflash .6s ease-out forwards;
}
@keyframes hitflash { 0% { opacity: 0; } 15% { opacity: 1; } 100% { opacity: 0; } }

/* ---------- Stitched cream pill (9-slice of assets/ui/pill.webp, 798×193, caps ≈ 96 px) ---------- */
.pill {
  --ph: 2.05em;
  display: inline-flex; align-items: center; justify-content: center;
  height: var(--ph);
  padding: 0 1.15em;
  border: 0 solid transparent;
  border-image-source: url("assets/ui/pill.webp");
  border-image-slice: 96 100 fill;
  border-image-width: calc(var(--ph) / 2) calc(var(--ph) * .53);
  border-image-repeat: stretch;
  color: var(--brown);
  font-weight: 800;
  letter-spacing: .02em;
  white-space: nowrap;
  line-height: 1;
  filter: drop-shadow(0 .1em .16em rgba(75, 35, 28, .38));
  margin: 0;
}

/* ---------- HUD ---------- */
.hud {
  position: absolute; left: 0; right: 0; top: 0;
  padding-top: max(4px, calc(var(--k) * 22px));
  display: flex; flex-direction: column; align-items: center;
  pointer-events: none;
  z-index: 10;
}
.hud-logo {
  display: block;
  width: calc(var(--k) * 384px); height: calc(var(--k) * 137.4px);
  filter: drop-shadow(0 calc(var(--k) * 5px) calc(var(--k) * 7px) rgba(60, 25, 10, .45));
  pointer-events: none;
}
#game.no-logo .hud-logo { display: none; }
#game.no-logo .hud { padding-top: max(6px, calc(var(--k) * 16px)); }

.hud-phase {
  font-size: max(11px, calc(var(--k) * 27px));
  --ph: 1.89em;
  margin-top: calc(var(--k) * 1px);
  min-width: calc(var(--k) * 200px);
  padding: 0 1.3em;
}

.hud-counts { display: flex; gap: max(5px, calc(var(--k) * 13px)); margin-top: calc(var(--k) * 1px); }
.hud-count {
  position: relative;
  font-size: max(11px, calc(var(--k) * 24px));
  --ph: 2.375em;
  width: max(9.2em, calc(var(--k) * 222px));
  justify-content: space-between;
  padding: 0 1.12em 0 2.62em;
  transform-origin: 50% 50%;
}
.hud-count .star {
  position: absolute; left: .02em; top: 50%; width: 2.1em; height: 2.1em; transform: translateY(-50%);
  filter: drop-shadow(0 .05em .05em rgba(90, 45, 10, .4));
}
.hud-count .who { font-size: .92em; letter-spacing: .03em; }
.hud-count.purl .who { color: var(--coral); }
.hud-count.loop .who { color: var(--teal); }
.hud-count .num { font-size: 1.08em; font-variant-numeric: tabular-nums; white-space: pre; }
.hud-count .num b { font-weight: 800; }
.hud-count.up { animation: pop .55s cubic-bezier(.2, 1.6, .4, 1); }
.hud-count.down { animation: shake .6s ease-in-out; }
@keyframes pop {
  0% { transform: scale(1); }
  35% { transform: scale(1.16); filter: drop-shadow(0 0 .5em rgba(255, 210, 90, .95)); }
  100% { transform: scale(1); }
}
@keyframes shake {
  0%, 100% { transform: translateX(0); color: var(--brown); }
  15% { transform: translateX(-.35em) rotate(-2deg); color: #b52248; }
  35% { transform: translateX(.3em) rotate(2deg); color: #b52248; }
  55% { transform: translateX(-.22em); color: #b52248; }
  75% { transform: translateX(.12em); }
}

.hud-objective {
  position: relative;
  font-size: max(10.5px, calc(var(--k) * 22px));
  --ph: 2.36em;
  margin-top: calc(var(--k) * 2.5px);
  min-width: max(15.5em, calc(var(--k) * 365px));
  max-width: calc(100% - 2 * var(--edge));
  padding: 0 3.3em 0 1.9em;
}
.hud-objective .txt { overflow: hidden; text-overflow: ellipsis; display: inline-block; }
.hud-objective .flag { position: absolute; right: .3em; top: 50%; width: 2.2em; height: 2.2em; transform: translateY(-52%); }
.hud-objective.is-message .txt { animation: msgIn .35s ease-out; }
.hud-objective.kind-hit .txt { color: #8e1d35; }
.hud-objective.kind-recover .txt { color: #0b6f62; }
@keyframes msgIn { from { transform: scale(.85); opacity: .2; } to { transform: scale(1); opacity: 1; } }

/* Slim race-progress thread: coral bead = Purl, teal bead = Loop (computer rival). */
.race-thread {
  position: relative;
  width: max(150px, calc(var(--k) * 330px));
  height: 10px;
  margin-top: max(3px, calc(var(--k) * 7px));
}
.race-thread::before {
  content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 3px; transform: translateY(-50%);
  border-radius: 2px;
  background: repeating-linear-gradient(90deg, #f6d888 0 5px, #c48a2c 5px 7px);
  box-shadow: 0 0 0 1px rgba(255, 248, 228, .85), 0 1px 3px rgba(60, 25, 10, .5);
}
.race-thread::after {
  content: ""; position: absolute; right: -4px; top: 50%; width: 8px; height: 8px; transform: translateY(-50%) rotate(45deg);
  background: var(--gold); border: 1.5px solid #fff3d2; border-radius: 2px;
}
.race-thread .bead {
  position: absolute; top: 50%; left: 0; width: 10px; height: 10px; margin: -5px 0 0 -5px;
  border-radius: 50%; border: 1.5px solid #fff6df;
  box-shadow: 0 1px 2px rgba(50, 20, 10, .55);
}
.race-thread .bead.purl { background: radial-gradient(circle at 35% 35%, #ff8d99, #e0344f 70%); z-index: 2; }
.race-thread .bead.loop { background: radial-gradient(circle at 35% 35%, #6fe0e2, #0b97a3 70%); width: 9px; height: 9px; margin: -4.5px 0 0 -4.5px; }

.hud-hint {
  margin-top: max(4px, calc(var(--k) * 10px));
  max-width: calc(100% - 4 * var(--edge));
  padding: .45em 1em;
  border-radius: 1.2em;
  background: linear-gradient(#fff8e8, #f6e3c4);
  border: 1.5px solid #fff6df;
  box-shadow: 0 0 0 1px #c7a480 inset, 0 2px 6px rgba(60, 25, 10, .35);
  color: var(--brown);
  font-size: max(11px, calc(var(--k) * 21px));
  font-weight: 700;
  text-align: center;
  line-height: 1.25;
  animation: msgIn .3s ease-out;
}

/* Results (approved 07): LEVEL 1 COMPLETE with flower ends, true ranks, times. */
.hud-results { display: flex; flex-direction: column; align-items: center; }
.result-title {
  position: relative;
  font-size: max(15px, calc(var(--k) * 34px));
  --ph: 1.7em;
  margin-top: calc(var(--k) * 15.5px);
  min-width: max(11em, calc(var(--k) * 361px));
  padding: 0 1.5em;
  letter-spacing: .03em;
}
.result-title .orn, .btn-play-again .orn {
  position: absolute; top: 50%; width: 1.5em; height: 1.5em; transform: translateY(-50%); z-index: 2;
  filter: drop-shadow(0 .05em .06em rgba(90, 45, 10, .45));
}
.result-title .orn.l { left: -.62em; } .result-title .orn.r { right: -.62em; }
.result-ranks, .result-times { gap: .45em; padding: 0 1.4em; }
.result-ranks {
  font-size: max(11.5px, calc(var(--k) * 24px));
  --ph: 1.71em;
  margin-top: calc(var(--k) * 4.5px);
  min-width: max(13em, calc(var(--k) * 307px));
}
.result-times {
  font-size: max(10.5px, calc(var(--k) * 19px));
  --ph: 1.9em;
  margin-top: calc(var(--k) * 6px);
  min-width: max(13em, calc(var(--k) * 290px));
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.result-ranks .p, .result-times .p { color: var(--coral); }
.result-ranks .l, .result-times .l { color: var(--teal); }
.result-ranks .dot, .result-times .dot { color: var(--brown); opacity: .75; }
.result-wait {
  margin-top: max(4px, calc(var(--k) * 8px));
  font-size: max(11px, calc(var(--k) * 21px)); font-weight: 800; color: #fff8e5;
  padding: .3em .9em; border-radius: 1em;
  background: rgba(0, 105, 118, .86);
  box-shadow: 0 0 0 1.5px #83dfd1 inset, 0 2px 6px rgba(0, 40, 45, .4);
}
.result-wait .dots i { font-style: normal; animation: blink 1.2s infinite; }
.result-wait .dots i:nth-child(2) { animation-delay: .2s; } .result-wait .dots i:nth-child(3) { animation-delay: .4s; }
@keyframes blink { 0%, 100% { opacity: .2; } 40% { opacity: 1; } }

/* Round stitched pause button, top-right. The image matches the approved size (Ø75 design px); the button itself
   is never smaller than 48 CSS px so it stays an easy touch target. */
.btn-pause {
  --pv: max(34px, calc(var(--k) * 75.5px));
  --hit: max(48px, var(--pv));
  position: absolute; z-index: 30;
  top: max(0px, calc(var(--k) * 76px - var(--hit) / 2));
  right: max(0px, calc(var(--k) * 55.5px - var(--hit) / 2));
  width: var(--hit); height: var(--hit);
  padding: 0; border: 0; border-radius: 50%;
  background: url("assets/ui/pause.webp") center / var(--pv) var(--pv) no-repeat;
  filter: drop-shadow(0 2px 3px rgba(60, 25, 10, .45));
  cursor: pointer; touch-action: manipulation;
}
.btn-pause:active { transform: scale(.93); }
#game.no-logo .btn-pause { top: max(0px, calc(max(6px, var(--k) * 16px) + max(11px, var(--k) * 27px) * .945 - var(--hit) / 2)); }

/* ---------- Buttons ---------- */
.btn-teal, .btn-cream {
  position: relative;
  display: flex; align-items: center; justify-content: center;
  min-height: 48px; min-width: 44px;
  border: 0 solid transparent;
  border-image-source: url("assets/ui/pill.webp");
  border-image-slice: 96 100 fill;
  border-image-repeat: stretch;
  background: none;
  font-weight: 900; letter-spacing: .04em;
  cursor: pointer; touch-action: manipulation;
  filter: drop-shadow(0 3px 4px rgba(60, 25, 10, .42));
}
.btn-teal { --bh: 52px; height: var(--bh); border-image-width: calc(var(--bh) / 2) calc(var(--bh) * .53); padding: 0; }
.btn-teal .face {
  position: absolute; inset: 12% 5% 14% 5%;
  display: flex; align-items: center; justify-content: center;
  border-radius: 999px;
  background:
    repeating-linear-gradient(100deg, rgba(255, 255, 255, .05) 0 3px, rgba(0, 0, 0, .04) 3px 6px),
    linear-gradient(180deg, #19b8bd 0%, var(--teal-bright) 35%, var(--teal-deep) 100%);
  box-shadow: inset 0 0 0 2px #83dfd1, inset 0 2px 0 rgba(255, 255, 255, .35), inset 0 -3px 4px rgba(0, 60, 70, .35);
  color: #fff8e5;
  font-size: 1.12em;
  text-shadow: 0 2px 0 rgba(0, 70, 80, .55);
}
.btn-cream { --bh: 48px; height: var(--bh); border-image-width: calc(var(--bh) / 2) calc(var(--bh) * .53); padding: 0 1.6em; color: var(--brown); font-size: 1em; }
.btn-teal:active, .btn-cream:active { transform: translateY(1px) scale(.98); }
.btn-teal:focus-visible, .btn-cream:focus-visible, .btn-pause:focus-visible, .btn-cashout:focus-visible { outline: 3px solid #ffd45c; outline-offset: 3px; }
.btn-wide { width: 100%; max-width: 290px; margin-left: auto; margin-right: auto; }

/* PLAY AGAIN (approved 07), just above the rewards strip. */
.btn-play-again {
  --bh: max(56px, calc(var(--k) * 94px));
  position: absolute; z-index: 30; left: 50%; transform: translateX(-50%);
  bottom: calc(var(--rw-bottom) + var(--rw-h) + max(6px, calc(var(--k) * 12px)));
  width: max(236px, calc(var(--k) * 392px));
  font-size: max(17px, calc(var(--k) * 34px));
  animation: rise .45s cubic-bezier(.2, 1.4, .4, 1);
}
.btn-play-again .face { font-size: 1em; }
.btn-play-again:active { transform: translateX(-50%) translateY(1px) scale(.98); }
.btn-play-again .orn { width: 1.55em; height: 1.55em; }
.btn-play-again .orn.l { left: -.5em; } .btn-play-again .orn.r { right: -.5em; }
@keyframes rise { from { transform: translateX(-50%) translateY(30px); opacity: 0; } to { transform: translateX(-50%); opacity: 1; } }

/* ---------- Saved rewards strip (placeholder only; locked cash out) ---------- */
.rewards {
  position: absolute; z-index: 20; left: 50%; transform: translateX(-50%);
  bottom: var(--rw-bottom);
  width: min(calc(100% - 2 * max(4px, calc(var(--k) * 30px))), max(300px, calc(var(--k) * 746px)));
  height: var(--rw-h);
  display: flex; align-items: center;
