// Usage: node cap.cjs <query> <w> <h> <dpr> <out.png> [script.js]
const { chromium } = require('/opt/node22/lib/node_modules/playwright');
(async () => {
  const [query, w, h, dpr, out, scriptFile] = process.argv.slice(2);
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: +w, height: +h }, deviceScaleFactor: +dpr, hasTouch: true, isMobile: +w < 700 });
  const page = await ctx.newPage();
  const logs = [];
  page.on('console', m => logs.push(m.type() + ': ' + m.text()));
  page.on('pageerror', e => logs.push('pageerror: ' + e.message));
  await page.goto('http://127.0.0.1:8102/game/index.html?' + query);
  await page.waitForFunction(() => window.WishweaveGame && window.WishweaveGame.debug, null, { timeout: 15000 });
  await page.evaluate(() => WishweaveGame.debug.screenshotReady());
  if (scriptFile) {
    const fn = require(require('path').resolve(scriptFile));
    await fn(page);
  }
  await page.screenshot({ path: out });
  console.log(logs.filter(l => !/favicon/.test(l)).join('\n'));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

