"""Measure HUD element boxes (cream pills) and text extents in design px for an approved PNG or a capture.
Usage: python3 hudmeasure.py <png> [--capture]   (capture is rescaled to 841 px wide first)"""
import sys
from collections import deque
from PIL import Image
import numpy as np

path = sys.argv[1]
im = Image.open(path).convert('RGB')
if im.width != 841 and '--raw' not in sys.argv:
    im = im.resize((841, round(im.height * 841 / im.width)), Image.LANCZOS)
a = np.asarray(im).astype(int)
R, G, B = a[..., 0], a[..., 1], a[..., 2]
cream = (R > 228) & (G > 212) & (B > 185) & ((R - B) < 70)


def comps(y0, y1, minn=1500):
    sub = cream[y0:y1].copy()
    H, W = sub.shape
    seen = np.zeros_like(sub)
    out = []
    for y in range(H):
        for x in range(W):
            if sub[y, x] and not seen[y, x]:
                q = deque([(y, x)]); seen[y, x] = 1; c = 0
                minx = maxx = x; miny = maxy = y
                while q:
                    cy, cx = q.popleft(); c += 1
                    minx = min(minx, cx); maxx = max(maxx, cx); miny = min(miny, cy); maxy = max(maxy, cy)
                    for ny, nx in ((cy + 1, cx), (cy - 1, cx), (cy, cx + 1), (cy, cx - 1)):
                        if 0 <= ny < H and 0 <= nx < W and sub[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = 1; q.append((ny, nx))
                if c >= minn:
                    out.append((minx, miny + y0, maxx - minx + 1, maxy - miny + 1, c))
    return sorted(out, key=lambda o: (o[1], o[0]))


def text(box):
    x0, y0, x1, y1 = box
    sub = a[y0:y1, x0:x1]
    lum = sub[..., 0] * .3 + sub[..., 1] * .59 + sub[..., 2] * .11
    d = lum < 150
    rows = np.where(d.sum(1) > 0)[0]; cols = np.where(d.sum(0) > 0)[0]
    if not len(rows):
        return None
    return (x0 + cols[0], y0 + rows[0], x0 + cols[-1], y0 + rows[-1], 'h=%d' % (rows[-1] - rows[0] + 1), 'w=%d' % (cols[-1] - cols[0] + 1))


print('TOP cream boxes (x y w h n):')
for o in comps(0, 430):
    print('  x=%d y=%d w=%d h=%d n=%d cy=%.0f cx=%.0f' % (o + (o[1] + o[3] / 2, o[0] + o[2] / 2)))
print('BOTTOM cream boxes:')
for o in comps(1580, min(a.shape[0], 1870)):
    print('  x=%d y=%d w=%d h=%d n=%d cy=%.0f cx=%.0f' % (o + (o[1] + o[3] / 2, o[0] + o[2] / 2)))

