// UI interaction checks against the stub harness with real touch input (CDP touch events).
const { chromium } = require('/opt/node22/lib/node_modules/playwright');
const BASE = 'http://127.0.0.1:8102/game/index.html?test=1&stubs=1';
const OUT = __dirname + '/';
let failures = 0;
function check(name, ok, extra) { console.log((ok ? 'PASS ' : 'FAIL ') + name + (extra !== undefined ? '  ' + JSON.stringify(extra) : '')); if (!ok) failures++; }

async function open(browser, query, vw = 412, vh = 915) {
  const ctx = await browser.newContext({ viewport: { width: vw, height: vh }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const page = await ctx.newPage();
  page.on('pageerror', e => { console.log('pageerror: ' + e.message); failures++; });
  await page.goto(BASE + '&' + query);
  await page.waitForFunction(() => window.WishweaveGame && WishweaveGame.debug);
  await page.evaluate(() => WishweaveGame.debug.screenshotReady());
  const cdp = await ctx.newCDPSession(page);
  return { ctx, page, cdp };
}
async function touch(cdp, pts, stepMs = 16) {
  // pts: [[x,y], ...] first = start, last = end
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: pts[0][0], y: pts[0][1], id: 1 }] });
  for (let i = 1; i < pts.length; i++) {
    await new Promise(r => setTimeout(r, stepMs));
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: pts[i][0], y: pts[i][1], id: 1 }] });
  }
  await new Promise(r => setTimeout(r, stepMs));
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await new Promise(r => setTimeout(r, 30));
}
const swipePts = (x, y, dx, dy, n = 6) => Array.from({ length: n + 1 }, (_, i) => [x + dx * i / n, y + dy * i / n]);
const st = (page, expr) => page.evaluate(new Function('return (' + expr + ')'));

(async () => {
  const browser = await chromium.launch();

  /* ---- 1. start, countdown, stitch tap with real touch ---- */
