    // tap pause
    await touch(cdp, [[pb.x + pb.width / 2, pb.y + pb.height / 2]]);
    check('pause button → paused + overlay', await st(page, "WishweaveGame.debug.race.state.paused && !document.getElementById('ov-pause').hidden"));
