    check('paused: advance does not move time', await st(page, "WishweaveGame.debug.race.state.time") === tPaused);
    // swipes on the canvas under the overlay are blocked
    await touch(cdp, swipePts(200, 650, 90, 0));
    check('no game input while paused', await st(page, "WishweaveGame.debug.race.state.purl.lane") === 0);
