    const hb = await page.locator('#btn-help').boundingBox();
    await touch(cdp, [[hb.x + hb.width / 2, hb.y + hb.height / 2]]);
    check('help panel shown', await st(page, "!document.getElementById('pause-help').hidden && document.getElementById('pause-menu').hidden"));
    check('onBack closes help → paused', await st(page, "WishweaveGame.onBack()") === 'paused' && await st(page, "document.getElementById('pause-help').hidden"));
    await page.screenshot({ path: OUT + 'i_pause.png' });
    const rb = await page.locator('#btn-resume').boundingBox();
    await touch(cdp, [[rb.x + rb.width / 2, rb.y + rb.height / 2]]);
    check('resume', await st(page, "!WishweaveGame.debug.race.state.paused && document.getElementById('ov-pause').hidden"));
    // lifecycle
    await page.evaluate(() => { Object.defineProperty(document, 'visibilityState', { value: 'hidden', configurable: true }); document.dispatchEvent(new Event('visibilitychange')); });
    check('visibility hidden → paused(background)', await st(page, "WishweaveGame.debug.race.state.paused && WishweaveGame.debug.race.state.pauseReason") === 'background');
    await page.evaluate(() => { Object.defineProperty(document, 'visibilityState', { value: 'visible', configurable: true }); document.dispatchEvent(new Event('visibilitychange')); });
    check('stays paused on return', await st(page, "WishweaveGame.debug.race.state.paused"));
    check('pause sub text explains', /away/.test(await st(page, "document.getElementById('pause-sub').textContent")));
    await page.evaluate(() => WishweaveGame.resume());
    await page.evaluate(() => window.dispatchEvent(new Event('blur')));
    check('blur → paused', await st(page, "WishweaveGame.debug.race.state.paused"));
    await page.evaluate(() => WishweaveGame.resume());
    await page.evaluate(() => window.dispatchEvent(new Event('pagehide')));
    check('pagehide → paused', await st(page, "WishweaveGame.debug.race.state.paused"));
    check('onBack while paused → exit', await st(page, "WishweaveGame.onBack()") === 'exit');
    await page.evaluate(() => WishweaveGame.resume());
    check('onBack while running → paused', await st(page, "WishweaveGame.onBack()") === 'paused' && await st(page, "WishweaveGame.debug.race.state.pauseReason") === 'back');
    // keyboard
    await page.keyboard.press('Escape');
    check('Esc resumes', await st(page, "!WishweaveGame.debug.race.state.paused"));
    await page.keyboard.press('ArrowRight');
    check('ArrowRight → lane 1', await st(page, "WishweaveGame.debug.race.state.purl.lane") === 1);
    await page.keyboard.press('p');
    check('P pauses', await st(page, "WishweaveGame.debug.race.state.paused"));
    await page.keyboard.press('p');
    // getState is a copy
    check('getState is a detached copy', await st(page, "(function(){ const s = WishweaveGame.getState(); s.held.purl = 99; return WishweaveGame.debug.race.state.held.purl !== 99; })()"));
    // cash out: note, strip unchanged
    const strip0 = await st(page, "document.getElementById('rewards').innerHTML");
    const cb = await page.locator('#btn-cashout').boundingBox();
    await touch(cdp, [[cb.x + cb.width / 2, cb.y + cb.height / 2]]);
    check('cash out shows locked note', await st(page, "!document.getElementById('cashout-note').hidden"));
    check('cash out did not pause/act', await st(page, "!WishweaveGame.debug.race.state.paused"));
    await page.screenshot({ path: OUT + 'i_cashout.png' });
