    await page.evaluate(() => { const d = WishweaveGame.debug; d.race.state.purl.lane = 0; d.race.state.purl.laneX = 0; d.race.state.purl.jumpT = 0; d.race.state.purl.jumpH = 0; d.race.debug.teleport('purl', 'landing', 0.2); d.advance(0.1); });
    for (let i = 0; i < 30; i++) { await page.evaluate(() => WishweaveGame.debug.advance(0.1)); if (await st(page, "WishweaveGame.debug.race.state.stats.hits") > 0) break; }
    check('hit → PURL 1/3', await st(page, "document.querySelector('#hud-purl .num b').textContent") === '1');
    check('hit → shake', await st(page, "document.getElementById('hud-purl').classList.contains('down')"));
    check('hit → SNAGGED! in objective pill', await st(page, "document.querySelector('#hud-objective .txt').textContent") === 'SNAGGED!');
    await page.screenshot({ path: OUT + 'i_snagged.png' });
    check('rewards strip unchanged after hit', await st(page, "document.getElementById('rewards').innerHTML") === strip0);
    // recover: swipe into the drop lane
    const lane = await st(page, "WishweaveGame.debug.race.state.items['purl.teal'].lane");
    await page.evaluate(() => WishweaveGame.debug.advance(0.6));
    await touch(cdp, swipePts(200, 650, lane > 0 ? 90 : -90, 0));
    let rec = false;
    for (let i = 0; i < 30 && !rec; i++) { await page.evaluate(() => WishweaveGame.debug.advance(0.1)); rec = await st(page, "WishweaveGame.debug.race.state.stats.recoveries") > 0; }
    check('recovery → THREAD RECOVERED', rec && await st(page, "document.querySelector('#hud-objective .txt').textContent") === 'THREAD RECOVERED');
    check('recovery → PURL 2/3 pop', await st(page, "document.querySelector('#hud-purl .num b').textContent") === '2' && await st(page, "document.getElementById('hud-purl').classList.contains('up')"));
    await page.screenshot({ path: OUT + 'i_recovered.png' });
  }

  /* ---- 3. fail → try again ---- */
  {
    const { page, cdp } = await open(browser, 'seed=13&scenario=fail');
    await page.evaluate(() => { const d = WishweaveGame.debug; d.setClock('manual'); WishweaveGame.start(); d.advance(3.2); d.race.debug.openAll(); d.race.debug.teleport('purl', 'landing', 0.2); d.advance(4); });
    check('hit at 0 → failed + fail overlay', await st(page, "WishweaveGame.debug.race.state.mode") === 'failed' && await st(page, "!document.getElementById('ov-fail').hidden"));
    await page.screenshot({ path: OUT + 'i_fail.png' });
    const strip0 = await st(page, "document.getElementById('rewards').innerHTML");
    const b = await page.locator('#btn-retry').boundingBox();
    await touch(cdp, [[b.x + b.width / 2, b.y + b.height / 2]]);
    check('TRY AGAIN → fresh countdown', await st(page, "WishweaveGame.debug.race.state.mode") === 'countdown' && await st(page, "WishweaveGame.debug.race.state.held.purl") === 0 && await st(page, "document.getElementById('ov-fail').hidden"));
    check('rewards strip unchanged after retry', await st(page, "document.getElementById('rewards').innerHTML") === strip0);
  }

  /* ---- 4. results → play again; real clock loop ---- */
  {
    const { page, cdp } = await open(browser, 'seed=14');
    await page.evaluate(() => { const d = WishweaveGame.debug; d.setClock('manual'); WishweaveGame.start(); d.advance(3.2); d.race.debug.openAll(); d.race.debug.forceFinish(false); d.advance(0.3); });
    check('finished: results shown, objective hidden', await st(page, "!document.getElementById('hud-results').hidden && document.getElementById('hud-objective').hidden"));
    check('Loop still racing chip', await st(page, "!document.getElementById('result-wait').hidden"));
    check('PLAY AGAIN delayed', await st(page, "document.getElementById('btn-play-again').hidden"));
    check('finished: background pauses while Loop races', await st(page, "WishweaveGame.onBack()") === 'paused');
    await page.evaluate(() => WishweaveGame.resume());
    await page.evaluate(() => WishweaveGame.debug.advance(12));
    check('Loop finished → ranks', /1st PURL.*2nd LOOP/.test(await st(page, "document.getElementById('result-ranks').textContent")), await st(page, "document.getElementById('result-ranks').textContent"));
    check('wait chip gone', await st(page, "document.getElementById('result-wait').hidden"));
    check('onBack after all finished → exit', await st(page, "WishweaveGame.onBack()") === 'exit');
    const b = await page.locator('#btn-play-again').boundingBox();
    check('PLAY AGAIN ≥ 44px tall', b && b.height >= 44, b);
    await touch(cdp, [[b.x + b.width / 2, b.y + b.height / 2]]);
    check('PLAY AGAIN → countdown', await st(page, "WishweaveGame.debug.race.state.mode") === 'countdown' && await st(page, "document.getElementById('hud-results').hidden"));
    await page.evaluate(() => WishweaveGame.debug.setClock('real'));
    await page.waitForTimeout(3600);
    const s = await st(page, "({mode: WishweaveGame.debug.race.state.mode, t: WishweaveGame.debug.race.state.time})");
    check('real clock: countdown → running', s.mode === 'running' && s.t > 0.2, s);
    // loser case
    await page.evaluate(() => { const d = WishweaveGame.debug; d.setClock('manual'); d.newRace(15); WishweaveGame.start(); d.advance(3.2); d.race.debug.openAll(); d.race.debug.forceFinish(true); d.advance(2); });
    check('Loop first → 1st LOOP · 2nd PURL', /1st LOOP.*2nd PURL/.test(await st(page, "document.getElementById('result-ranks').textContent")), await st(page, "document.getElementById('result-ranks').textContent"));
    await page.screenshot({ path: OUT + 'i_loopwins.png' });
  }

  /* ---- 5. API: restart(seed), seed param, start before load ---- */
  {
    const { page } = await open(browser, 'seed=99');
    check('?seed=N fixes the seed', await st(page, "WishweaveGame.debug.seed") === 99);
    await page.evaluate(() => WishweaveGame.restart(1234));
    check('restart(seed) starts countdown with that seed', await st(page, "WishweaveGame.debug.seed") === 1234 && await st(page, "WishweaveGame.debug.race.state.mode") === 'countdown');
    check('version', typeof await st(page, "WishweaveGame.version") === 'string');
  }

