const { chromium } = require('/opt/node22/lib/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 412, height: 915 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const page = await ctx.newPage();
  const logs = []; page.on('console', m => logs.push(m.type() + ': ' + m.text())); page.on('pageerror', e => logs.push('pageerror: ' + e.message));
  await page.goto('http://127.0.0.1:8102/game/index.html?test=1&seed=7');
  await page.waitForFunction(() => window.WishweaveGame && WishweaveGame.debug);
  await page.evaluate(() => WishweaveGame.debug.screenshotReady());
  const cdp = await ctx.newCDPSession(page);
  const tap = async (x, y) => { await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x, y, id: 1 }] }); await new Promise(r => setTimeout(r, 40)); await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] }); await new Promise(r => setTimeout(r, 30)); };
  await page.evaluate(() => { const d = WishweaveGame.debug; d.setClock('manual'); WishweaveGame.start(); d.advance(3.3); });
  const out = [];
  for (const id of ['ribbon', 'shortcut', 'tassels', 'butterfly']) {
    let t = [];
    for (let i = 0; i < 400 && !t.length; i++) { await page.evaluate(() => WishweaveGame.debug.advance(0.25)); t = await page.evaluate(() => WishweaveGame.debug.targets()); if (await page.evaluate(() => WishweaveGame.debug.race.state.mode) !== 'running') break; }
    const s = await page.evaluate(() => { const st = WishweaveGame.debug.race.state; return { mode: st.mode, seg: st.purl.segId, f: +st.purl.f.toFixed(3), time: +st.time.toFixed(2), held: st.held, obj: st.objective, msg: st.message && st.message.text, hint: st.hint && st.hint.text }; });
    out.push(['target', id, JSON.stringify(t), JSON.stringify(s)].join(' '));
    if (!t.length) break;
    if (id === 'ribbon') await page.screenshot({ path: __dirname + '/real_stitch.png' });
    await tap(t[0].x, t[0].y);
    const after = await page.evaluate((id) => WishweaveGame.debug.race.state.stitches[id].state, t[0].id);
    out.push('  after touch tap: ' + t[0].id + ' ' + after);
  }
  for (let i = 0; i < 300; i++) { const m = await page.evaluate(() => { WishweaveGame.debug.advance(0.5); return WishweaveGame.debug.race.state.mode; }); if (m !== 'running') break; }
  const fin = await page.evaluate(() => { const st = WishweaveGame.debug.race.state; return { mode: st.mode, seg: st.purl.segId, held: st.held, result: st.result, time: st.time, stats: st.stats, hud: document.querySelector('#hud-purl .num b').textContent, ranks: document.getElementById('result-ranks').textContent }; });
  out.push('end ' + JSON.stringify(fin));
  await page.screenshot({ path: __dirname + '/real_end.png' });
  await page.evaluate(() => WishweaveGame.debug.advance(30));
  out.push('later ' + JSON.stringify(await page.evaluate(() => ({ result: WishweaveGame.debug.race.state.result, ranks: document.getElementById('result-ranks').textContent, times: document.getElementById('result-times').textContent, wait: !document.getElementById('result-wait').hidden, again: !document.getElementById('btn-play-again').hidden }))));
  await page.screenshot({ path: __dirname + '/real_results.png' });
  console.log(out.join('\n'));
  console.log(logs.slice(0, 20).join('\n'));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
EOF
timeout 240 node real_run.cjs

